-- แถวที่ status เป็น NULL จะหลุดไป
SELECT * FROM orders WHERE status <> 'paid';

-- ถ้าต้องการรวมแถว NULL ด้วย
SELECT * FROM orders
WHERE status <> 'paid' OR status IS NULL;

-- COUNT(*) นับทุกแถว ส่วน COUNT(email) ข้าม NULL
SELECT COUNT(*), COUNT(email) FROM customers;

CREATE TABLE orders (
  id          BIGINT PRIMARY KEY,
  customer_id BIGINT NOT NULL REFERENCES customers(id),
  total       NUMERIC(12,2) NOT NULL CHECK (total >= 0),
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX ON orders (customer_id);

BEGIN;
UPDATE accounts SET balance = balance - 500 WHERE id = 1;
UPDATE accounts SET balance = balance + 500 WHERE id = 2;
COMMIT;  -- ถ้ามี error ระหว่างทางให้ ROLLBACK ทั้งชุด

-- ออเดอร์ล่าสุดของลูกค้าแต่ละคน
WITH ranked AS (
  SELECT o.*,
         ROW_NUMBER() OVER (
           PARTITION BY customer_id
           ORDER BY created_at DESC
         ) AS rn
  FROM orders o
)
SELECT * FROM ranked WHERE rn = 1;

-- 1) expand
ALTER TABLE users ADD COLUMN full_name TEXT;
-- 2) migrate: โค้ดเขียนทั้งสองคอลัมน์ + backfill ทีละชุด
UPDATE users SET full_name = name
WHERE full_name IS NULL AND id BETWEEN 1 AND 10000;
-- 3) deploy โค้ดที่อ่าน full_name
-- 4) contract (release ถัดไป)
ALTER TABLE users DROP COLUMN name;

// อันตราย: ค่าจากผู้ใช้กลายเป็นส่วนหนึ่งของ SQL
db.query("SELECT * FROM users WHERE email = '" + email + "'");

// ปลอดภัย: node-postgres ใช้ $1, $2, ...
db.query('SELECT * FROM users WHERE email = $1', [email]);

-- อ่านแล้วค่อยเขียน: เสี่ยง lost update
SELECT stock FROM products WHERE id = 7;   -- ได้ 10
UPDATE products SET stock = 9 WHERE id = 7;

-- อะตอมในคำสั่งเดียว และกันสต็อกติดลบ
UPDATE products SET stock = stock - 1
WHERE id = 7 AND stock > 0;

-- ลูกค้าที่มีออเดอร์ paid อย่างน้อย 1 รายการ (ไม่มีแถวซ้ำ)
SELECT c.name
FROM customers c
WHERE EXISTS (
  SELECT 1 FROM orders o
  WHERE o.customer_id = c.id AND o.status = 'paid'
);

-- ลูกค้าที่ไม่เคยมีออเดอร์เลย
SELECT c.name
FROM customers c
WHERE NOT EXISTS (
  SELECT 1 FROM orders o WHERE o.customer_id = c.id
);

SET TIME ZONE 'UTC';
SELECT TIMESTAMPTZ '2025-03-01 00:00:00+07';
-- 2025-02-28 17:00:00+00
SET TIME ZONE 'Asia/Bangkok';
SELECT TIMESTAMPTZ '2025-03-01 00:00:00+07';
-- 2025-03-01 00:00:00+07 (ค่าเดียวกัน แสดงตามโซน)
SELECT TIMESTAMP '2025-03-01 00:00:00+07';
-- 2025-03-01 00:00:00 (+07 ถูกตัดทิ้ง)

-- ทุก transaction แตะบัญชีที่ id น้อยกว่าก่อนเสมอ
-- (โอนจากบัญชี 2 ไป 1 ก็ปรับลำดับ UPDATE ในโค้ดให้แตะ 1 ก่อน)
BEGIN;
UPDATE accounts SET balance = balance - 500 WHERE id = 1;
UPDATE accounts SET balance = balance + 500 WHERE id = 2;
COMMIT;

-- ตารางไหนมีแถวตายสะสมมาก
SELECT relname, n_live_tup, n_dead_tup, last_autovacuum
FROM pg_stat_user_tables
ORDER BY n_dead_tup DESC
LIMIT 10;

VACUUM (VERBOSE, ANALYZE) orders;

