WHERE status = 'pending'
ORDER BY id LIMIT 1;

UPDATE jobs SET status = 'running' WHERE id = $1;

CREATE INDEX idx_jobs_pending ON jobs (created_at)
  WHERE status = 'pending';

EXPLAIN SELECT * FROM jobs
WHERE created_at < now() - interval '1 hour';

